package io.github.turbopro.ism.bootstrap;
import org.junit.jupiter.api.Test;
import org.springframework.http.HttpStatus;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;
class SitePreferenceIT extends SitePreferenceSupport {
    @org.springframework.beans.factory.annotation.Autowired io.github.turbopro.ism.iam.site.SitePreferenceService preferences;
    @org.springframework.beans.factory.annotation.Autowired io.github.turbopro.ism.common.infrastructure.authorization.AuthorizationGrantLoader grants;
    @org.springframework.beans.factory.annotation.Autowired org.springframework.transaction.PlatformTransactionManager transactions;
    @Test void versionWriteUsesCurrentReadDespiteOlderTransactionSnapshot(){
        var f=fixture();String t=tenantLogin(f,"pref-admin");
        try(var tenant=io.github.turbopro.ism.common.infrastructure.tenant.TenantContext.open(f.tenant(),f.admin());var auth=io.github.turbopro.ism.common.infrastructure.authorization.AuthorizationContext.open(grants.load(f.tenant(),f.admin()))){
            new org.springframework.transaction.support.TransactionTemplate(transactions).execute(status->{
                assertThat(preferences.state().version()).isZero();
                assertThat(save(t,"external",f.first(),0).getStatusCode()).isEqualTo(HttpStatus.OK);
                var changed=preferences.save(new io.github.turbopro.ism.iam.site.SitePreferenceModels.Update(Long.toString(f.second()),1));
                assertThat(changed.state().version()).isEqualTo(2);return null;
            });
        }
    }
    @Test void optionsAreScopedSearchableAndPaged(){var f=fixture();String t=tenantLogin(f,"pref-admin");var r=request("GET","/api/site-preferences/options?size=1",t,null,null);assertThat(r.getStatusCode()).isEqualTo(HttpStatus.OK);assertThat(r.getBody().path("data").path("total").asLong()).isEqualTo(2);assertThat(r.getBody().path("data").path("items").size()).isOne();assertThat(r.getBody().toString()).doesNotContain(Long.toString(f.headquarters()),"第一车间");var second=request("GET","/api/site-preferences/options?q=SECOND",t,null,null);assertThat(second.getBody().path("data").path("total").asLong()).isOne();assertThat(second.getBody().toString()).contains(Long.toString(f.second()));assertThat(request("GET","/api/site-preferences/options?q=%25",t,null,null).getBody().path("data").path("total").asLong()).isZero();assertThat(request("GET","/api/site-preferences/options?size=101",t,null,null).getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);}
    @Test void membershipsAndDataScopesIntersectIncludingDepartment(){var f=fixture();String admin=tenantLogin(f,"pref-admin"),reader=tenantLogin(f,"pref-reader");assertThat(request("GET","/api/site-preferences/options",reader,null,null).getBody().path("data").path("total").asLong()).isOne();narrow(f,"ORGANIZATION_SET",f.second());var r=request("GET","/api/site-preferences/options",admin,null,null);assertThat(r.getBody().path("data").path("total").asLong()).isOne();assertThat(r.getBody().toString()).contains(Long.toString(f.second())).doesNotContain(Long.toString(f.first()));narrow(f,"NONE",0);assertThat(request("GET","/api/site-preferences/options",admin,null,null).getBody().path("data").path("total").asLong()).isZero();jdbc.update("UPDATE iam_organization SET status='DISABLED' WHERE tenant_id=? AND id=?",f.tenant(),f.department());assertThat(request("GET","/api/site-preferences/options",reader,null,null).getBody().path("data").path("total").asLong()).isZero();}
    @Test void personalSaveReplayClearDoNotChangeOrganization(){var f=fixture();String t=tenantLogin(f,"pref-admin");var org=jdbc.queryForList("SELECT * FROM iam_user_context WHERE tenant_id=? ORDER BY user_id",f.tenant());var first=save(t,"save",f.first(),0);assertThat(first.getStatusCode()).isEqualTo(HttpStatus.OK);assertThat(first.getBody().path("data").path("version").asInt()).isOne();assertThat(save(t,"save",f.first(),0).getBody().path("data")).isEqualTo(first.getBody().path("data"));assertThat(save(t,"old-version",f.second(),0).getStatusCode()).isEqualTo(HttpStatus.CONFLICT);assertThat(request("GET","/api/site-preferences",tenantLogin(f,"pref-reader"),null,null).getBody().path("data").path("version").asInt()).isZero();var clear=save(t,"clear",null,1);assertThat(clear.getStatusCode()).isEqualTo(HttpStatus.OK);assertThat(clear.getBody().path("data").path("preferredSite").isNull()).isTrue();assertThat(clear.getBody().path("data").path("version").asInt()).isEqualTo(2);assertThat(jdbc.queryForList("SELECT * FROM iam_user_context WHERE tenant_id=? ORDER BY user_id",f.tenant())).isEqualTo(org);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM sys_audit_event WHERE tenant_id=? AND action='SITE_PREFERENCE_CHANGE'",Integer.class,f.tenant())).isEqualTo(2);}
    @Test void revokedStoredChoiceAndReplayAreFailClosed(){var f=fixture();String t=tenantLogin(f,"pref-admin");assertThat(save(t,"original",f.first(),0).getStatusCode()).isEqualTo(HttpStatus.OK);narrow(f,"ORGANIZATION_SET",f.second());var read=request("GET","/api/site-preferences",t,null,null);assertThat(read.getBody().path("data").path("unavailable").asBoolean()).isTrue();assertThat(read.getBody().toString()).doesNotContain(Long.toString(f.first()),"第一工厂");assertThat(save(t,"original",f.first(),0).getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);assertThat(jdbc.queryForObject("SELECT version FROM iam_user_site_preference WHERE tenant_id=? AND user_id=?",Integer.class,f.tenant(),f.admin())).isOne();assertThat(save(t,"clear-revoked",null,1).getStatusCode()).isEqualTo(HttpStatus.OK);}
    @Test void siteAndAncestorDisableHideStoredChoice(){var f=fixture();String t=tenantLogin(f,"pref-admin");assertThat(save(t,"set",f.second(),0).getStatusCode()).isEqualTo(HttpStatus.OK);jdbc.update("UPDATE iam_organization SET status='DISABLED' WHERE tenant_id=? AND id=?",f.tenant(),f.headquarters());assertThat(request("GET","/api/site-preferences/options",t,null,null).getBody().path("data").path("total").asLong()).isZero();assertThat(request("GET","/api/site-preferences",t,null,null).getBody().path("data").path("unavailable").asBoolean()).isTrue();assertThat(save(t,"set",f.second(),0).getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);}
    @Test void readonlyAndForeignTargetsCannotWrite(){var f=fixture();var foreign=fixture();String reader=tenantLogin(f,"pref-reader"),admin=tenantLogin(f,"pref-admin");assertThat(request("GET","/api/site-preferences",reader,null,null).getBody().path("data").path("canManage").asBoolean()).isFalse();assertThat(save(reader,"reader",f.first(),0).getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);assertThat(save(admin,"foreign",foreign.first(),0).getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);assertThat(save(admin,"headquarters",f.headquarters(),0).getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);assertThat(count("iam_user_site_preference",f.tenant())).isZero();}
    @Test void auditFailureRollsBackAndRetries()throws Exception{var f=fixture();String t=tenantLogin(f,"pref-admin");trigger("CREATE TRIGGER pref_audit_failure BEFORE INSERT ON sys_audit_event FOR EACH ROW BEGIN IF NEW.action='SITE_PREFERENCE_CHANGE' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic preference audit failure'; END IF; END");try{assertThat(save(t,"retry",f.first(),0).getStatusCode()).isEqualTo(HttpStatus.INTERNAL_SERVER_ERROR);assertThat(count("iam_user_site_preference",f.tenant())).isZero();}finally{trigger("DROP TRIGGER pref_audit_failure");}assertThat(save(t,"retry",f.first(),0).getStatusCode()).isEqualTo(HttpStatus.OK);}
    @Test void competingInitialSavesHaveOneWinner()throws Exception{var f=fixture();String t=tenantLogin(f,"pref-admin");var a=CompletableFuture.supplyAsync(()->save(t,"a",f.first(),0));var b=CompletableFuture.supplyAsync(()->save(t,"b",f.second(),0));assertThat(List.of(a.get(30,TimeUnit.SECONDS).getStatusCode(),b.get(30,TimeUnit.SECONDS).getStatusCode())).containsExactlyInAnyOrder(HttpStatus.OK,HttpStatus.CONFLICT);assertThat(count("iam_user_site_preference",f.tenant())).isOne();}
}
